/*
 * A286685  {0->01, 1->10}-transform of the Pell word, A171588.
 * https://oeis.org/A286685
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = p_{ceil(n/2)} XOR ((n+1)&1) where p_k is the k-th term of
 *            the Pell word (A171588), generated by the morphism 0 → 001, 1 →
 *            0
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>

/* Static storage for the Pell word */
static seq_t *pell = NULL;   /* array of 0/1 values */
static idx_t  pell_len = 0;  /* current length of pell */

/* Ensure that pell contains at least m symbols (1‑based indexing). */
static void ensure_pell(idx_t m)
{
    if (pell_len >= m)
        return;

    /* initialise if necessary */
    if (pell_len == 0) {
        pell = (seq_t *)malloc(sizeof(seq_t));
        if (!pell) exit(EXIT_FAILURE);
        pell[0] = 0;
        pell_len = 1;
    }

    /* grow until length >= m */
    while (pell_len < m) {
        /* count zeros and ones in current word */
        size_t zeros = 0, ones = 0;
        for (idx_t i = 0; i < pell_len; ++i) {
            if (pell[i] == 0)
                ++zeros;
            else
                ++ones;
        }

        /* new length after one application of the morphism */
        size_t new_len = zeros * 3 + ones;

        seq_t *np = (seq_t *)malloc(new_len * sizeof(seq_t));
        if (!np) exit(EXIT_FAILURE);

        /* build the next word */
        idx_t pos = 0;
        for (idx_t i = 0; i < pell_len; ++i) {
            if (pell[i] == 0) {
                np[pos++] = 0;
                np[pos++] = 0;
                np[pos++] = 1;
            } else {
                np[pos++] = 0;
            }
        }

        free(pell);
        pell = np;
        pell_len = new_len;
    }
}

seq_t a(idx_t n)
{
    /* m = ceil(n/2) */
    idx_t m = (n + 1) / 2;
    ensure_pell(m);

    seq_t p = pell[m - 1];                     /* Pell word bit (0‑based) */
    seq_t toggle = (((seq_t)n + 1) & 1);        /* 1 if n even, else 0  */
    return p ^ toggle;
}
